select energy_manager.load_cards($cards$[
{"id":"p3-086","paper":3,"topic":"Lighting","kind":"fact","front":"What is Lighting Power Density (LPD), and how is the lighting power allowance calculated?","back":"LPD = installed lighting watts ÷ floor area (W/m²). Allowance = LPD limit × floor area. For example, 14 floors × 1000 m² × 10.8 W/m² = 1,51,200 W.","explain":"ECBC sets maximum LPD values by building type (building area method) or by space (space function method). Lower installed LPD for the same lux means a more efficient design.","flash":false,"source":"BEE 2024 P3 Q24","order":3085},
{"id":"p3-087","paper":3,"topic":"Lighting","kind":"fact","front":"What is ILER, and how is it interpreted?","back":"Installed Load Efficacy Ratio = actual installed load efficacy (lux/W/m²) ÷ target efficacy for that application. ILER of 0.75 or above is satisfactory; 0.51–0.74 needs review; 0.5 or below needs urgent action.","explain":"Installed load efficacy = average maintained lux ÷ (installed W/m²). It is a quick audit indicator of how well the lighting system converts power into useful illuminance.","flash":false,"source":"syllabus","order":3086},
{"id":"p3-088","paper":3,"topic":"Lighting","kind":"problem","front":"A 20 m × 15 m workshop needs 400 lux. Luminaires are 36 W LED, each producing 4000 lumens. Utilisation factor is 0.65 and maintenance factor is 0.8. Find the number of luminaires, the installed LPD, and the installed load efficacy (lux/W/m²).","back":"58 luminaires; LPD ≈ 6.96 W/m²; installed load efficacy ≈ 57.5 lux/W/m².","explain":"The lumen method divides the total lumens needed on the working plane by the effective lumens per luminaire after UF and MF. The LPD check is what ECBC compliance looks at. Installed load efficacy compared with the target gives the ILER.","steps":[{"prompt":"Find the area and total lumens required.","answer":"A = 300 m²; Φ = 400 × 300 = 1,20,000 lm","explain":"Φ = E × A."},{"prompt":"Find the effective lumens per luminaire.","answer":"4000 × 0.65 × 0.8 = 2080 lm","explain":"Lamp lumens × UF × MF."},{"prompt":"Find the number of luminaires.","answer":"1,20,000 / 2080 = 57.7, so 58","explain":"Always round up."},{"prompt":"Find the installed load and LPD.","answer":"58 × 36 = 2088 W; 2088/300 = 6.96 W/m²","explain":"LPD = W/m²."},{"prompt":"Find the installed load efficacy.","answer":"400 / 6.96 ≈ 57.5 lux/W/m²","explain":"Lux ÷ W/m²."}],"flash":false,"source":"BEE 2025 P3 S-1 (similar)","order":3087},
{"id":"p3-089","paper":3,"topic":"DG sets","kind":"fact","front":"How is hourly fuel consumption of a DG set found from kVA, PF and specific fuel consumption?","back":"Fuel (L/h) = kVA × PF × SFC (L/kWh). For example, 1250 kVA × 0.8 × 0.23 = 230 L/h; 1000 kVA × 0.7 × 0.25 = 175 L/h.","explain":"kVA × PF gives kW, and kW × 1 h × L/kWh gives litres. The inverse, kWh per litre (specific energy generation), is the usual DG performance indicator. Typical well-loaded DG sets achieve about 3–4 kWh/L.","flash":true,"source":"BEE 2024 P3 Q18 / BEE 2025 P3 Q46","order":3088},
{"id":"p3-090","paper":3,"topic":"DG sets","kind":"fact","front":"In a DG set, which loss is the largest?","back":"Flue (exhaust) gas loss, followed by cooling water (jacket) loss.","explain":"Only about 30–40% of fuel energy becomes electricity. The hot exhaust (typically 400–500°C) can drive a waste heat boiler or VAM, especially when the DG runs continuously. Stack exit temperature is kept above the acid dew point.","flash":false,"source":"BEE 2025 P3 Q5 / BEE 2024 P3 S1","order":3089},
{"id":"p3-091","paper":3,"topic":"DG sets","kind":"fact","front":"How do altitude and high ambient temperature affect a DG set?","back":"They reduce power output (the set must be derated), because thinner, hotter air holds less oxygen mass for combustion.","explain":"Manufacturers give derating factors for altitude, ambient temperature and humidity. Choose the DG capacity using site-derated output, not nameplate rating.","flash":false,"source":"BEE 2024 P3 Q14","order":3090},
{"id":"p3-092","paper":3,"topic":"DG sets","kind":"fact","front":"Name good operating practices for DG set energy efficiency.","back":"Load the set near its optimum (typically above about 60–70%); avoid low-load running; operate parallel sets to share load sensibly; keep phase loads balanced; maintain PF near the rated 0.8 or above; keep intake air cool and clean; recover exhaust heat; monitor kWh per litre.","explain":"Alternator losses rise at low PF because higher current is drawn for the same kW, so alternator losses are not independent of PF. DG sets are not designed to tolerate large phase unbalance (such as 25%); unbalance causes alternator overheating.","flash":false,"source":"BEE 2025 P3 L-2","order":3091},
{"id":"p3-093","paper":3,"topic":"DG sets","kind":"problem","front":"A 500 kVA DG set (rated PF 0.8) supplies an average of 320 kW for 1 hour on test and consumes 95 litres of diesel (density 0.85 kg/L, GCV 10,800 kcal/kg). Find the percentage loading, specific energy generation (kWh/L), overall thermal efficiency, and the fuel cost per kWh at Rs 90/L.","back":"Loading 80%; ≈ 3.37 kWh/L; efficiency ≈ 31.6%; ≈ Rs 26.7/kWh.","explain":"DG performance is tracked by kWh per litre (or its inverse, SFC in L/kWh). Overall efficiency = electrical output (kWh × 860 kcal/kWh) ÷ fuel heat input. A falling kWh/L trend signals poor loading, injector or turbocharger problems.","steps":[{"prompt":"Find the percentage loading.","answer":"Rated kW = 500 × 0.8 = 400 kW; loading = 320/400 = 80%","explain":"Loading on kW rating."},{"prompt":"Find the specific energy generation.","answer":"320 kWh / 95 L = 3.37 kWh/L (SFC = 0.297 L/kWh)","explain":"kWh per litre."},{"prompt":"Find the fuel heat input.","answer":"95 × 0.85 = 80.75 kg; × 10,800 = 8,72,100 kcal","explain":"Mass × GCV."},{"prompt":"Find the thermal efficiency.","answer":"320 × 860 / 8,72,100 = 31.6%","explain":"1 kWh = 860 kcal."},{"prompt":"Find the fuel cost per kWh.","answer":"90 / 3.37 ≈ Rs 26.7/kWh","explain":"Fuel price ÷ kWh/L."}],"flash":false,"source":"BEE 2025 P3 L-5 / Q46 (similar)","order":3092},
{"id":"p3-094","paper":3,"topic":"Energy-efficient technologies","kind":"fact","front":"Why does a VFD save the most energy on centrifugal pumps and fans?","back":"These are variable-torque loads whose power varies with speed³. Matching speed to demand, instead of throttling, captures cube-law savings.","explain":"Constant-torque loads (conveyors, positive-displacement pumps, screw compressors) save roughly in proportion to speed, so savings are smaller but still worthwhile where output varies. VFDs also give soft starting. The trade-offs are VFD losses (about 2–4%) and harmonic generation.","flash":false,"source":"syllabus","order":3093}
]$cards$::jsonb);
